SELECT 
FROM scene_definition
WHERE user_id = #{userId}
  AND deleted = 0

    AND trigger_type = #{triggerType}


    AND enabled = #{enabled}


    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY id DESC

SELECT COUNT(*)
FROM scene_definition
WHERE user_id = #{userId}
  AND deleted = 0
  AND name = #{name}

    AND id != #{excludeId}

mapper.update:
UPDATE scene_definition
SET last_triggered_at = #{triggeredAt,jdbcType=TIMESTAMP}
WHERE id = #{id}

UPDATE scene_definition
SET last_triggered_at = #{triggeredAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND (last_triggered_at IS NULL OR last_triggered_at < #{minuteFloor,jdbcType=TIMESTAMP})
